  for (const part of String(raw).split(',')) {
    const item = part.trim();
    if (item && !seen.has(item)) {
      seen.add(item);
      out.push(item);
    }
  }
  return out;
}

function deepFreeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const key of Object.keys(value)) deepFreeze(value[key]);
  }
  return value;
}

/**
 * Copy only the known configuration keys out of an env-like source.
 * Works with n8n's $env proxy, which may throw when env access is blocked.
 */
function snapshotEnv(source) {
  const env = {};
  let blocked = false;
  if (!source || (typeof source !== 'object' && typeof source !== 'function')) {
    return { env, blocked };
  }
  for (const key of CONFIG_ENV_KEYS) {
    try {
      const value = source[key];
      if (value !== undefined && value !== null) env[key] = String(value);
    } catch (error) {
      blocked = true;
    }
  }
  return { env, blocked };
}

/**
 * Parse and validate configuration.
 * @param {Record<string,string>} env plain object of environment variables
 * @param {{context?: 'provisioning'|'approval'}} [options]
 * @returns {{config: object, errors: string[], warnings: string[], ok: boolean}}
 */
function loadConfig(env, options) {
  const source = env || {};
  const context = (options && options.context) || 'provisioning';
  if (!CONFIG_CONTEXTS.includes(context)) {
    throw new Error('Unknown config context: ' + context);
  }
  const errors = [];
  const warnings = [];
  const read = (key) => {
    const value = source[key];
    return value === undefined || value === null ? '' : String(value).trim();
  };

  // --- Sandbox (fail-safe) -------------------------------------------------
  let sandboxMode = true;
  const rawSandbox = read('SANDBOX_MODE');
  if (rawSandbox !== '') {
    const parsed = parseBooleanFlag(rawSandbox);
    if (parsed === null) {
      errors.push('SANDBOX_MODE must be "true" or "false" (got "' + rawSandbox + '"); sandbox remains ENABLED.');
    } else {
      sandboxMode = parsed;
    }
  }

  // --- HubSpot -------------------------------------------------------------
  const closedWonStageId = read('HUBSPOT_CLOSED_WON_STAGE_ID') || 'closedwon';
  const pipelineId = read('HUBSPOT_PIPELINE_ID');
  const portalId = read('HUBSPOT_PORTAL_ID');
  if (portalId && !/^\d{1,20}$/.test(portalId)) errors.push('HUBSPOT_PORTAL_ID must be numeric.');
  const intakeNotesProperty = read('HUBSPOT_INTAKE_NOTES_PROPERTY') || 'deal_intake_notes';
  if (!HUBSPOT_PROPERTY_NAME_PATTERN.test(intakeNotesProperty)) {
    errors.push('HUBSPOT_INTAKE_NOTES_PROPERTY must be a HubSpot internal property name (lowercase, digits, underscores).');
  }
  const appClientSecret = read('HUBSPOT_APP_CLIENT_SECRET');
  const webhookTargetUrl = read('HUBSPOT_WEBHOOK_TARGET_URL');
  if (appClientSecret && !/^https:\/\/\S+$/.test(webhookTargetUrl)) {
    errors.push('HUBSPOT_WEBHOOK_TARGET_URL (https) is required when HUBSPOT_APP_CLIENT_SECRET is set, because HubSpot v3 signatures cover the exact URL.');
  }

  // --- Slack ---------------------------------------------------------------
  const approvalChannel = read('SLACK_INTERNAL_APPROVAL_CHANNEL') || '#cs-handoffs';
  if (!SLACK_CHANNEL_REF_PATTERN.test(approvalChannel)) {
    errors.push('SLACK_INTERNAL_APPROVAL_CHANNEL must be a channel ID (e.g. C0123ABCD) or a #channel-name.');
  }
  const channelPrefixRaw = read('SLACK_CHANNEL_PREFIX') || 'client';
  const channelPrefix = channelPrefixRaw.toLowerCase();
  if (!/^[a-z0-9][a-z0-9_-]{0,19}$/.test(channelPrefix)) {
    errors.push('SLACK_CHANNEL_PREFIX must be 1-20 chars of lowercase letters, digits, hyphens or underscores.');
  }
  let privateChannels = true;
  const rawPrivate = read('SLACK_PRIVATE_CHANNELS');
  if (rawPrivate !== '') {
    const parsed = parseBooleanFlag(rawPrivate);
    if (parsed === null) errors.push('SLACK_PRIVATE_CHANNELS must be "true" or "false".');
    else privateChannels = parsed;
  }
  const internalMemberIds = parseCsvList(read('SLACK_INTERNAL_MEMBER_IDS'));
  const approverIds = parseCsvList(read('APPROVER_SLACK_USER_IDS'));
  for (const id of internalMemberIds) {
    if (!SLACK_USER_ID_PATTERN.test(id)) errors.push('SLACK_INTERNAL_MEMBER_IDS contains an invalid Slack user ID: ' + id);
  }
  for (const id of approverIds) {
    if (!SLACK_USER_ID_PATTERN.test(id)) errors.push('APPROVER_SLACK_USER_IDS contains an invalid Slack user ID: ' + id);
  }
  const signingSecret = read('SLACK_SIGNING_SECRET');
  const tolerance = parseIntegerInRange(read('SLACK_SIGNATURE_TOLERANCE_SECONDS'), 300, 30, 900);
  if (tolerance.error) errors.push('SLACK_SIGNATURE_TOLERANCE_SECONDS ' + tolerance.error + '.');

  // --- Google Drive --------------------------------------------------------
  const driveParentFolderId = read('DRIVE_PARENT_FOLDER_ID');
  if (driveParentFolderId && !/^[A-Za-z0-9_-]{10,128}$/.test(driveParentFolderId)) {
    errors.push('DRIVE_PARENT_FOLDER_ID does not look like a Google Drive folder ID.');
  }

  // --- Workspace provider --------------------------------------------------
  const workspaceProvider = (read('WORKSPACE_PROVIDER') || 'clickup').toLowerCase();
  if (!SUPPORTED_WORKSPACE_PROVIDERS.includes(workspaceProvider)) {
    errors.push('WORKSPACE_PROVIDER must be one of: ' + SUPPORTED_WORKSPACE_PROVIDERS.join(', ') + '.');
  }
  const workspaceContainerId = read('WORKSPACE_CONTAINER_ID');
  if (workspaceContainerId && !/^[A-Za-z0-9_-]{1,128}$/.test(workspaceContainerId)) {
    errors.push('WORKSPACE_CONTAINER_ID contains unsupported characters.');
  }

  // --- LLM -----------------------------------------------------------------
  const llmProvider = (read('LLM_PROVIDER') || 'none').toLowerCase();
  if (!SUPPORTED_LLM_PROVIDERS.includes(llmProvider)) {
    errors.push('LLM_PROVIDER must be one of: ' + SUPPORTED_LLM_PROVIDERS.join(', ') + '.');
  }
  const llmModel = read('LLM_MODEL');
  const maxTokens = parseIntegerInRange(read('LLM_MAX_TOKENS'), 1200, 200, 8000);
  if (maxTokens.error) errors.push('LLM_MAX_TOKENS ' + maxTokens.error + '.');
  let temperature = null;
  const rawTemperature = read('LLM_TEMPERATURE');
  if (rawTemperature !== '') {
    const t = Number(rawTemperature);
    if (!Number.isFinite(t) || t < 0 || t > 1) errors.push('LLM_TEMPERATURE must be a number between 0 and 1.');
    else temperature = t;
  }
  if (llmProvider !== 'none' && !llmModel) {
    errors.push('LLM_MODEL is required when LLM_PROVIDER is "' + llmProvider + '".');
  }

  // --- External invite safety ---------------------------------------------
  const invitePolicy = (read('EXTERNAL_INVITE_DOMAIN_POLICY') || 'match_company_domain').toLowerCase();
  if (!SUPPORTED_INVITE_POLICIES.includes(invitePolicy)) {
    errors.push('EXTERNAL_INVITE_DOMAIN_POLICY must be one of: ' + SUPPORTED_INVITE_POLICIES.join(', ') + '.');
  }
  const allowedDomains = parseCsvList(read('EXTERNAL_INVITE_ALLOWED_DOMAINS').toLowerCase());
  if (invitePolicy === 'allowlist' && allowedDomains.length === 0) {
    errors.push('EXTERNAL_INVITE_ALLOWED_DOMAINS must list at least one domain when EXTERNAL_INVITE_DOMAIN_POLICY=allowlist.');
  }
  const maxInvites = parseIntegerInRange(read('MAX_EXTERNAL_INVITES'), 10, 1, 50);
  if (maxInvites.error) errors.push('MAX_EXTERNAL_INVITES ' + maxInvites.error + '.');

  // --- Misc ----------------------------------------------------------------
  const orgDisplayName = (read('ORG_DISPLAY_NAME') || 'Our Team').slice(0, 80);
  const lockTtl = parseIntegerInRange(read('IDEMPOTENCY_LOCK_TTL_MINUTES'), 15, 1, 1440);
  if (lockTtl.error) errors.push('IDEMPOTENCY_LOCK_TTL_MINUTES ' + lockTtl.error + '.');

  // --- Mode/context-specific requirements ---------------------------------
  if (!sandboxMode) {
    if (context === 'provisioning') {
      if (!driveParentFolderId) errors.push('DRIVE_PARENT_FOLDER_ID is required when SANDBOX_MODE=false.');
      if (!workspaceContainerId) errors.push('WORKSPACE_CONTAINER_ID is required when SANDBOX_MODE=false.');
      if (internalMemberIds.length === 0) {
        errors.push('SLACK_INTERNAL_MEMBER_IDS must list at least one internal Slack user when SANDBOX_MODE=false (bot-created channels have no human members otherwise).');
      }
    }
    if (approverIds.length === 0) {
      errors.push('APPROVER_SLACK_USER_IDS must list at least one approver when SANDBOX_MODE=false.');
    }
    if (!appClientSecret && context === 'provisioning') {
      warnings.push('HUBSPOT_APP_CLIENT_SECRET is not set: inbound HubSpot webhook signatures are not verified. Deal data is still re-fetched from the HubSpot API before any action.');
    }
  } else {
    warnings.push('SANDBOX_MODE is enabled: no channels, folders, projects, invites or CRM writes will be executed.');
    if (approverIds.length === 0) {
      warnings.push('APPROVER_SLACK_USER_IDS is empty: any workspace user may click sandbox approval buttons.');
    }
  }
  if (context === 'approval' && !signingSecret) {
    errors.push('SLACK_SIGNING_SECRET is required for the approval dispatcher (signatures are verified in every mode).');
  }

  const dealProperties = HUBSPOT_BASE_DEAL_PROPERTIES.concat(
    Object.values(HUBSPOT_ONBOARDING_PROPERTIES),
    [intakeNotesProperty]
  );

  const config = {
    context,
    sandboxMode,
    hubspot: {
      closedWonStageId,
      pipelineId,
      portalId,
      intakeNotesProperty,
      appClientSecret,
      webhookTargetUrl,
      properties: Object.assign({}, HUBSPOT_ONBOARDING_PROPERTIES),
      dealProperties: Array.from(new Set(dealProperties))
    },
    slack: {
      approvalChannel,
      channelPrefix,
      privateChannels,
      internalMemberIds,
      approverIds,
      signingSecret,
      signatureToleranceSeconds: tolerance.value
    },
    drive: {
      parentFolderId: driveParentFolderId
    },
    workspace: {
      provider: workspaceProvider,
      containerId: workspaceContainerId
    },
    llm: {
      provider: llmProvider,
      model: llmModel,
      maxTokens: maxTokens.value,
      temperature
    },
    invites: {
      policy: invitePolicy,
      allowedDomains,
      maxPerDeal: maxInvites.value
    },
    org: {
      displayName: orgDisplayName
    },
    idempotency: {
      lockTtlMs: lockTtl.value * 60 * 1000,
      ledgerMaxEntries: 500
    }
  };

  return { config: deepFreeze(config), errors, warnings, ok: errors.length === 0 };
}

/**
 * Like loadConfig, but throws a single descriptive Error when invalid.
 */
function requireValidConfig(env, options) {
  const result = loadConfig(env, options);
  if (!result.ok) {
    throw new Error('Invalid configuration:\n - ' + result.errors.join('\n - '));
  }
  return result;
}

/**
 * Safe-to-log copy of the config: secrets are replaced, never echoed.
 */
function redactConfig(config) {
  const copy = JSON.parse(JSON.stringify(config));
  if (copy.slack) copy.slack.signingSecret = copy.slack.signingSecret ? '[REDACTED]' : '';
  if (copy.hubspot) copy.hubspot.appClientSecret = copy.hubspot.appClientSecret ? '[REDACTED]' : '';
  return copy;
}
// ---- src/sanitizer.js ----
/**
 * src/sanitizer.js
 * Input payload normalizer & validator for HubSpot Deal, Company and Contact
 * objects, plus safe name builders for Slack channels and Drive folders.
 *
 * Accepts both HubSpot CRM v3 API shapes ({ id, properties: {...} }) and
 * flat objects, so the same logic serves live webhooks, tests and samples.
 */

const LEGAL_SUFFIXES = new Set([
  'inc', 'incorporated', 'llc', 'ltd', 'limited', 'corp', 'corporation', 'co',
  'company', 'gmbh', 'plc', 'pty', 'sa', 'sarl', 'bv', 'ag', 'llp', 'lp', 'srl'
]);

const SLACK_CHANNEL_MAX_LENGTH = 80;
const DRIVE_FOLDER_NAME_MAX_LENGTH = 100;
const INTAKE_NOTES_MAX_LENGTH = 8000;
const DEAL_ID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;
const DOMAIN_PATTERN = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$/;
const EMAIL_PATTERN = /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$/;

function stripControlChars(value) {
  return String(value === undefined || value === null ? '' : value).replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u2028\u2029\ufeff]/g, ' ');
}

function sanitizeSingleLineText(value, maxLength) {
  const limit = maxLength || 255;
  return stripControlChars(value).replace(/\s+/g, ' ').trim().slice(0, limit).trim();
}

function decodeBasicEntities(text) {
  return text
    .replace(/&nbsp;/gi, ' ')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&amp;/gi, '&');
}

/**
 * Normalise multi-line free text (e.g. HubSpot rich-text intake notes):
 * converts block HTML to newlines, strips tags, decodes common entities,
 * removes control characters, collapses blank lines and caps the length.
 */
function sanitizeMultilineText(value, maxLength) {
  const limit = maxLength || INTAKE_NOTES_MAX_LENGTH;
  let text = String(value === undefined || value === null ? '' : value);
  text = text.replace(/\r\n?/g, '\n');
  text = text.replace(/<\s*br\s*\/?>/gi, '\n').replace(/<\/\s*(p|div|li|h[1-6])\s*>/gi, '\n');
  text = text.replace(/<\s*li[^>]*>/gi, '- ');
  text = text.replace(/<[^>]*>/g, '');
  text = decodeBasicEntities(text);
  text = text.replace(/[\u0000-\u0008\u000b-\u001f\u007f-\u009f\u200b-\u200f\u2028\u2029\ufeff]/g, '');
  text = text.split('\n').map((line) => line.replace(/[ \t]+/g, ' ').trim()).join('\n');
  text = text.replace(/\n{3,}/g, '\n\n').trim();
  if (text.length > limit) text = text.slice(0, limit).trim() + '\n[truncated]';
  return text;
}

function normalizeDomain(input) {
  let domain = String(input === undefined || input === null ? '' : input).trim().toLowerCase();
  if (!domain) return '';
  domain = domain.replace(/^[a-z][a-z0-9+.-]*:\/\//, '');
  domain = domain.split(/[/?#]/)[0];
  domain = domain.replace(/^.*@/, '');
  domain = domain.replace(/:\d+$/, '');
  domain = domain.replace(/^www\./, '');
  domain = domain.replace(/\.+$/, '');
  return DOMAIN_PATTERN.test(domain) ? domain : '';
}

function normalizeEmail(email) {
  return String(email === undefined || email === null ? '' : email).trim().toLowerCase();
}

function isValidEmail(email) {
  const value = normalizeEmail(email);
  if (!value || value.length > 254) return false;
  const at = value.lastIndexOf('@');
  if (at < 1) return false;
  const local = value.slice(0, at);
  if (local.length > 64 || local.startsWith('.') || local.endsWith('.') || local.includes('..')) return false;
  return EMAIL_PATTERN.test(value);
}

function emailDomain(email) {
  const value = normalizeEmail(email);
  const at = value.lastIndexOf('@');
  return at === -1 ? '' : value.slice(at + 1);
}

/**
 * True when `domain` equals `parent` or is a subdomain of it.
 */
function domainMatches(domain, parent) {
  const d = normalizeDomain(domain);
  const p = normalizeDomain(parent);
  if (!d || !p) return false;
  return d === p || d.endsWith('.' + p);
}

function slugifyCompanyName(name, options) {
  const opts = options || {};
  const maxLength = opts.maxLength || 50;
  const base = stripControlChars(name)
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/['\u2019`]/g, '');
  const tokens = base.split(/[^a-z0-9]+/).filter(Boolean);
  if (opts.stripLegalSuffixes !== false) {
    while (tokens.length > 1 && LEGAL_SUFFIXES.has(tokens[tokens.length - 1])) tokens.pop();
    while (tokens.length > 1 && tokens[tokens.length - 1] === 'and') tokens.pop();
  }
  let slug = tokens.join('-');
  if (slug.length > maxLength) slug = slug.slice(0, maxLength).replace(/-+$/, '');
  return slug;
}

/**
 * Build a Slack-safe channel name: `<prefix>-<slug>-onboarding`.
 * Slack rules: lowercase, max 80 chars, letters/digits/hyphens/underscores.
 */
function buildSlackChannelName(companyName, options) {
  const opts = options || {};
  const prefix = slugifyCompanyName(opts.prefix || 'client', { stripLegalSuffixes: false, maxLength: 20 }) || 'client';
  const suffix = 'onboarding';
  const maxSlugLength = SLACK_CHANNEL_MAX_LENGTH - prefix.length - suffix.length - 2;
  let slug = slugifyCompanyName(companyName, { maxLength: maxSlugLength });
  if (!slug) {
    const fallbackId = String(opts.fallbackId || '').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 20);
    if (!fallbackId) {
      throw new Error('Cannot build Slack channel name: company name has no usable characters and no fallback ID was provided.');
    }
    slug = 'deal-' + fallbackId;
  }
  return prefix + '-' + slug + '-' + suffix;
}

/**
 * Parse HubSpot dates: ISO strings, epoch-millisecond numbers/strings, Date.
 */
function parseHubSpotDate(value) {
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : new Date(value.getTime());
  if (value === undefined || value === null || value === '') return null;
  const raw = String(value).trim();
  const date = /^\d{10,14}$/.test(raw) ? new Date(Number(raw)) : new Date(raw);
  return Number.isNaN(date.getTime()) ? null : date;
}

function formatYearMonth(date) {
  return date.getUTCFullYear() + '-' + String(date.getUTCMonth() + 1).padStart(2, '0');
}

function formatIsoDate(date) {
  return formatYearMonth(date) + '-' + String(date.getUTCDate()).padStart(2, '0');
}

/**
 * Build the Drive root folder name: `YYYY-MM - <Company Name>` (UTC month).
 */
function formatDriveFolderName(companyName, dateInput) {
  const date = parseHubSpotDate(dateInput);
  if (!date) throw new Error('Cannot format Drive folder name: invalid date "' + dateInput + '".');
  const cleanName = stripControlChars(companyName)
    .replace(/[\\/:*?"<>|]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^\.+/, '')
    .trim();
  if (!cleanName) throw new Error('Cannot format Drive folder name: company name is empty after sanitization.');
  const prefix = formatYearMonth(date) + ' - ';
  return (prefix + cleanName).slice(0, DRIVE_FOLDER_NAME_MAX_LENGTH).trim();
}

function readProperty(record, name) {
  if (!record || typeof record !== 'object') return undefined;
  const props = record.properties;
  if (props && Object.prototype.hasOwnProperty.call(props, name)) {
    const value = props[name];
    if (value && typeof value === 'object' && 'value' in value) return value.value;
    return value;
  }
  if (Object.prototype.hasOwnProperty.call(record, name)) return record[name];
  return undefined;
}

function parseAmount(value) {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(String(value).replace(/[,\s]/g, ''));
  return Number.isFinite(n) ? n : null;
}

function normalizeContact(raw) {
  const email = normalizeEmail(readProperty(raw, 'email'));
  return {
    id: String(raw && (raw.id || readProperty(raw, 'hs_object_id')) || ''),
    email,
    firstName: sanitizeSingleLineText(readProperty(raw, 'firstname') || readProperty(raw, 'firstName'), 80),
    lastName: sanitizeSingleLineText(readProperty(raw, 'lastname') || readProperty(raw, 'lastName'), 80),
    jobTitle: sanitizeSingleLineText(readProperty(raw, 'jobtitle') || readProperty(raw, 'jobTitle'), 120),
    isPrimary: Boolean(raw && (raw.isPrimary === true || readProperty(raw, 'is_primary_contact') === 'true'))
  };
}

function contactsArray(input) {
  if (!input) return [];
  if (Array.isArray(input)) return input;
  if (Array.isArray(input.results)) return input.results;
  return [];
}

/**
 * Normalise and validate a HubSpot deal + company + contacts bundle.
 * @returns {{ok:boolean, errors:string[], warnings:string[], value:object|null}}
 */
function normalizeDealPayload(input, options) {
  const opts = options || {};
  const intakeProp = opts.intakeNotesProperty || 'deal_intake_notes';
  const errors = [];
  const warnings = [];
  const payload = input || {};
  const rawDeal = payload.deal;
  const rawCompany = payload.company;

  if (!rawDeal || typeof rawDeal !== 'object') {
    return { ok: false, errors: ['Missing deal object.'], warnings, value: null };
  }

  const dealId = String(rawDeal.id || readProperty(rawDeal, 'hs_object_id') || rawDeal.dealId || '').trim();
  if (!DEAL_ID_PATTERN.test(dealId)) errors.push('Deal ID is missing or malformed.');

  const stageId = sanitizeSingleLineText(readProperty(rawDeal, 'dealstage'), 64);
  if (!stageId) errors.push('Deal stage (dealstage) is missing.');

  const closeDate = parseHubSpotDate(readProperty(rawDeal, 'closedate'));
  if (!closeDate) warnings.push('Deal close date missing or invalid; provisioning date will be used for folder naming.');

  let company = null;
  if (!rawCompany || typeof rawCompany !== 'object' || rawCompany.status === 'error' || rawCompany.error) {
    errors.push('Associated company is missing (a deal must be associated with exactly one primary company).');
  } else {
    const companyName = sanitizeSingleLineText(readProperty(rawCompany, 'name'), 120);
    const rawDomain = readProperty(rawCompany, 'domain') || readProperty(rawCompany, 'website');
    const domain = normalizeDomain(rawDomain);
    if (!companyName) errors.push('Company name is missing.');
    if (!domain) errors.push('Company domain is missing or invalid ("' + sanitizeSingleLineText(rawDomain, 80) + '").');
    company = {
      id: String(rawCompany.id || readProperty(rawCompany, 'hs_object_id') || ''),
      name: companyName,
      domain
    };
  }

  let dealName = sanitizeSingleLineText(readProperty(rawDeal, 'dealname'), 150);
  if (!dealName) {
    dealName = company && company.name ? company.name + ' - New Deal' : 'Untitled Deal';
    warnings.push('Deal name missing; using "' + dealName + '".');
  }

  const seenEmails = new Set();
  const contacts = [];
  for (const raw of contactsArray(payload.contacts)) {
    const contact = normalizeContact(raw);
    if (!contact.email) {
      warnings.push('Contact ' + (contact.id || '(unknown id)') + ' has no email and was skipped.');
      continue;
    }
    if (!isValidEmail(contact.email)) {
      warnings.push('Contact ' + (contact.id || '(unknown id)') + ' has an invalid email and was skipped.');
      continue;
    }
    if (seenEmails.has(contact.email)) continue;
    seenEmails.add(contact.email);
    contacts.push(contact);
  }
  if (contacts.length === 0) warnings.push('No valid client contacts found; no external invites will be proposed.');
  if (contacts.length > 0 && !contacts.some((c) => c.isPrimary)) contacts[0].isPrimary = true;

  const value = {
    deal: {
      id: dealId,
      name: dealName,
      stageId,
      pipelineId: sanitizeSingleLineText(readProperty(rawDeal, 'pipeline'), 64),
      amount: parseAmount(readProperty(rawDeal, 'amount')),
      currency: (sanitizeSingleLineText(readProperty(rawDeal, 'deal_currency_code'), 3) || 'USD').toUpperCase(),
      closeDate: closeDate ? closeDate.toISOString() : null,
      ownerId: sanitizeSingleLineText(readProperty(rawDeal, 'hubspot_owner_id'), 32),
      intakeNotes: sanitizeMultilineText(readProperty(rawDeal, intakeProp)),
      onboardingStatus: sanitizeSingleLineText(readProperty(rawDeal, 'onboarding_status'), 40).toLowerCase(),
      storedIdempotencyKey: sanitizeSingleLineText(readProperty(rawDeal, 'onboarding_idempotency_key'), 64),
      storedSlackChannelId: sanitizeSingleLineText(readProperty(rawDeal, 'onboarding_slack_channel_id'), 32)
